string dw_str = is34dw ? "3DW" : "4DW";
        bit    m_is34dw = is34dw;
        bit [31:0] rdata, rdata_tmp;
        pcie_m_rd_seq  pmr_seq;
        pmr_seq = pcie_m_rd_seq::type_id::create("pmr_seq");
        if(p_sequencer.m_pcie_cfg.m_3dw_4dw inside {[0:1]}) begin
            dw_str = p_sequencer.m_pcie_cfg.m_3dw_4dw ? "3DW" : "4DW";
            m_is34dw = p_sequencer.m_pcie_cfg.m_3dw_4dw;
        end
        m_atomic.get(1);
        pmr_seq.s_m_read(.addr(addr), .is34dw(m_is34dw), .gap(gap), .seqr(p_sequencer));
        glbGetTrigger($sformatf("Tag0x%0h@WR_RAM_FPGA_MIRROR@0x%0h", pmr_seq.my_tag1, addr));
        m_atomic.put(1);
        rdata = pcie_pkg::FPGA_RAM_MIRROR[addr][`DATA_WIDTH*8-1:0];
        if (big_d) begin
          rdata_tmp = pcie_pkg::FPGA_RAM_MIRROR[addr][`DATA_WIDTH*8-1:0];
          for (int i=0;i<4;i++) begin
              rdata[i*8+:8] = rdata_tmp[31-i*8-:8];
          end
        end
        if (rdata == expdata) begin
        `uvm_info($sformatf("PCIE_REG_RD@%0s",dw_str), $sformatf("@ADDR[0x%0h] -> DATA[0x%0h]",addr,rdata),UVM_LOW);
        end else begin
          `uvm_info($sformatf("PCIE_REG_RD@%0s",dw_str), $sformatf("*E @ADDR[0x%0h] -> DATA[0x%0h] != EXP[0x%0h]",addr,rdata,expdata),UVM_LOW);
        end
    endtask

bit [31:0] rdata_tmp;

      m_pcie_seq.PCIE_REG_RD(addr, rdata_tmp);
